insert into public.exercises (
  id, key, name, primary_muscle, secondary_muscles, equipment, category, tracking_type,
  load_mode, instructions, created_at, updated_at
) values
  ('20c1d792-d5ae-4854-bcbd-ca0c299a3785', 'high-to-low-cable-fly', 'High-to-low cable fly', 'chest', array['shoulders']::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Set both pulleys above head height. With a slight bend in the elbows, sweep the handles down and together in front of the lower chest, then let them return slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('c228b8b8-2552-4e44-8af6-5b6b41d21b68', 'low-to-high-cable-fly', 'Low-to-high cable fly', 'chest', array['shoulders']::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Set both pulleys near the floor. With soft elbows, sweep the handles up and together to about chin height, then lower them slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('58e2552c-e7d4-4fbd-9658-1544f1abdf3e', 'deficit-push-up', 'Deficit push-up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Put the hands on push-up handles or plates so the chest can go below hand level. Keep the body straight, lower until the chest passes the hands, then push away.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('a38474d4-1496-4d6f-b2b0-7b8d5521d3aa', 'neutral-grip-pull-up', 'Neutral-grip pull-up', 'back', array['biceps']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Hang from parallel handles with the palms facing each other. Pull the chest up by driving the elbows down to the sides, then lower to a full hang.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f2fa5a14-7874-48b6-af95-58c1096e5785', 'machine-pullover', 'Machine pullover', 'back', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Sit with the pads on the backs of the upper arms and the arms overhead. Drive the elbows down and around to the sides, then let them rise slowly to a full stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('96932750-ed76-4856-9275-16f3a1f0dbce', 'one-arm-cable-lat-pull-in', 'One-arm cable lat pull-in', 'back', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Kneel or stand beside a high cable holding a single handle with a long arm. Pull the hand down and in towards the hip in an arc, keeping the elbow nearly straight, then return slowly. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('c8212a12-7afe-415c-936a-e35dfd4e573c', 'wide-elbow-chest-supported-row', 'Wide-elbow chest-supported row', 'back', array['shoulders', 'biceps']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Lie face down on an incline bench with a dumbbell in each hand. Row with the elbows flared out to the sides until the upper arms are level with the back, then lower. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('b573a090-eca2-4776-a0ab-d1f1413ae745', '45-degree-hip-back-extension', '45-degree hip back extension', 'glutes', array['hamstrings', 'back']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Set the pad just below the hips on a 45-degree bench. Hinge at the hips with a neutral spine, then squeeze the glutes to rise until the body is in a straight line. Hold a plate for more load.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5d869c4c-fe46-40bc-b6ee-0cac61711bb0', 'reverse-hyperextension', 'Reverse hyperextension', 'glutes', array['hamstrings', 'back']::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Lie face down on the machine with the hips at the edge and the legs hanging. Lift the legs behind you to body height by squeezing the glutes, then lower with control.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('2bba5cdb-73d4-4ea1-ad7f-ff7535572bb5', 'incline-prone-y-raise', 'Incline prone Y raise', 'back', array['shoulders']::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Lie face down on an incline bench with light dumbbells. Raise the arms up and out into a Y, thumbs up, until they line up with the body, then lower slowly. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('06fc34fe-5b17-4da5-aca4-1e9b19061f5b', 'cable-shrug', 'Cable shrug', 'back', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Stand between two low pulleys, or at one with a bar. Lift the shoulders straight up towards the ears, pause, then lower to a full stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('905d9841-d83a-4ed5-9591-149b2d8fa71c', 'bayesian-cable-rear-delt-fly', 'Bayesian cable rear-delt fly', 'shoulders', array['back']::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Stand side-on to a cable at shoulder height and take the handle with the far hand. With a soft elbow, sweep the arm out and back to the side of the body, then return slowly. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f5711573-0938-4785-9122-f50ccdea7beb', 'cable-external-rotation', 'Cable external rotation', 'shoulders', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Set a cable at elbow height and stand side-on. Keep the elbow bent to 90 degrees and against the side, and rotate the hand out away from the body, then back slowly. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d31a73ef-5d72-4bb9-bf23-4ffe8d9c5b6d', 'cable-internal-rotation', 'Cable internal rotation', 'shoulders', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Set a cable at elbow height and stand side-on with the near hand on the handle. Keep the elbow bent to 90 degrees against the side and rotate the hand in across the stomach, then back slowly. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('3eab1d0f-7898-4419-9792-d726f514db38', 'push-up-plus', 'Push-up plus', 'shoulders', array['chest', 'triceps']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Do a push-up, then at the top push the floor further away so the shoulder blades spread around the ribs. Lower the shoulder blades back, then the body.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('0f8b8ccc-798c-4d44-839e-52dd1d068b9c', 'spider-curl', 'Spider curl', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Lie chest down on an incline bench with the arms hanging straight. Curl the dumbbells up without moving the upper arms, squeeze, then lower to straight arms. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e401d752-0b12-4bd8-ba60-ab0ce10edb41', 'bayesian-cable-curl', 'Bayesian cable curl', 'biceps', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Face away from a low cable holding the handle, with the arm drawn slightly behind the body. Curl the hand to the shoulder without letting the elbow drift forward, then lower to a full stretch. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('0e27785c-1f14-4dfc-a8f7-2298e966d744', 'reverse-ez-bar-curl', 'Reverse EZ-bar curl', 'biceps', array[]::text[], 'barbell', 'isolation', 'weight_reps', 'total', 'Hold an EZ bar with the palms facing down. Keep the elbows at your sides and curl up without letting the wrists drop, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('69cebd2b-4201-4032-8aea-a5dab5159790', 'cross-body-cable-triceps-extension', 'Cross-body cable triceps extension', 'triceps', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Stand between two high pulleys, each hand holding the opposite cable so the arms cross. Straighten the elbows out to the sides, then let them bend back slowly. Both arms at once, or one at a time and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('9a6fd953-9da0-4c7a-9a91-d48011f833e9', 'seated-wrist-curl', 'Seated wrist curl', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Sit with the forearms on the thighs, palms up and wrists past the knees. Let the dumbbells roll down to the fingers, then curl the wrists up as far as they go. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('3e833c29-9eab-4be0-81e1-8f75f1240f30', 'reverse-wrist-curl', 'Reverse wrist curl', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Sit with the forearms on the thighs, palms down and wrists past the knees. Lift the backs of the hands up as far as they go, then lower slowly. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('a7bbd61e-1df6-4170-8f63-3c754d7ea3c0', 'wrist-pronation', 'Wrist pronation', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'total', 'Rest the forearm on a bench holding a dumbbell by one end, thumb side up. Turn the palm down slowly, then back to the start. Do one hand, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('4d57e233-549f-47dc-9405-a7a64902fbd7', 'wrist-supination', 'Wrist supination', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'total', 'Rest the forearm on a bench holding a dumbbell by one end, palm down. Turn the palm up slowly, then back to the start. Do one hand, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('10c7283c-a574-4e5e-8c93-ebf9d1b18f0b', 'dead-hang', 'Dead hang', 'back', array[]::text[], 'bodyweight', 'isolation', 'duration', 'total', 'Hang from a bar with an overhand grip and straight arms, shoulders lightly engaged. Hold for time.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f8eb6a92-e3e0-4d1e-823b-dc0059a79391', 'reverse-nordic-curl', 'Reverse Nordic curl', 'quads', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Kneel upright with the feet anchored or free. Keeping hips and torso in one line, lean back as far as you control, then use the quads to return to upright.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('aba8ccb4-4dcc-49a6-879d-e69095773f91', 'sissy-squat', 'Sissy squat', 'quads', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Hold a support and rise onto the toes. Let the knees travel forward as you lean back in one straight line from knees to head, lower as far as comfortable, then return.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('3fe7a376-bb48-489c-955e-d66a4d693be6', 'smith-machine-heel-elevated-squat', 'Smith machine heel-elevated squat', 'quads', array['glutes', 'adductors']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Stand under the Smith bar with the heels raised on a plate or wedge and the feet slightly forward. Squat down with an upright torso as deep as you control, then drive up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e853cc4b-687f-4a9a-b1a3-a4c2dde2e772', 'standing-single-leg-curl', 'Standing single-leg curl', 'hamstrings', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Stand in the machine with the pad behind one ankle and the hips against the support. Curl the heel up towards the glute, then lower slowly to a straight leg. Do one leg, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d25f0eec-37a2-491a-bc7e-00f5b1750fea', 'glute-ham-raise', 'Glute-ham raise', 'hamstrings', array['glutes']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Lock the ankles in the bench with the knees on the pad. Lower the upper body forward under control until it is level, then curl back up with the hamstrings, keeping the hips straight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('be94ab6d-4f60-4f6f-8472-67e6d1a257e9', 'cable-hip-abduction', 'Cable hip abduction', 'glutes', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Fit an ankle strap to a low cable and stand side-on with the outer leg strapped. Lift the leg out to the side without leaning, then lower slowly. Do one leg, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('8f4bc906-147d-4595-bab5-7223797c1748', 'cable-standing-hip-adduction', 'Cable standing hip adduction', 'adductors', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Fit an ankle strap to a low cable and stand side-on with the near leg strapped. Pull the leg across in front of the standing leg, then return slowly. Do one leg, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('639b6af0-f01f-4d18-a2e8-a55e1543577c', 'copenhagen-adduction', 'Copenhagen adduction', 'adductors', array['abs']::text[], 'bodyweight', 'isolation', 'duration', 'total', 'Lie on your side with the top leg on a bench and the forearm on the floor. Lift the hips so the body is straight, held up by the top leg. Hold for time, then switch sides.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('75dd402e-82d5-4c0f-9e57-48ff613bc35b', 'standing-cable-hip-flexion', 'Standing cable hip flexion', 'quads', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Fit an ankle strap to a low cable and face away from it. Drive the knee up to hip height without leaning back, then lower slowly. Do one leg, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('74db26f7-1c0b-4607-8d5d-9224e59e773a', 'seated-hip-flexion-raise', 'Seated hip flexion raise', 'quads', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Sit tall on a bench or the floor. Lift one knee or straight leg as high as you can without leaning back, pause, then lower. Do one leg, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('fd3b984f-23b9-4632-9769-6bd9adf1df9a', 'donkey-calf-raise', 'Donkey calf raise', 'calves', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Bend at the hips with the pad on the lower back and the balls of the feet on the step. Lower the heels to a full stretch, pause, then rise as high as you can.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ed09a16c-8281-4826-a2b7-0561ad3ffb71', 'tibialis-raise', 'Tibialis raise', 'calves', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Lean back against a wall with the heels a foot or so in front. Lift the toes and fronts of the feet as high as you can, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d35eb517-7707-4c1e-a903-2ced1d2c2be1', 'banded-ankle-eversion', 'Banded ankle eversion', 'calves', array[]::text[], 'band', 'isolation', 'weight_reps', 'total', 'Sit with a band around the outside of one foot, anchored to the inside. Turn the sole of the foot outwards against the band, then return slowly. Do one foot, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('05ef4447-744c-4f1d-9485-55e1b9949714', 'reverse-crunch-posterior-pelvic-tilt', 'Reverse crunch with posterior pelvic tilt', 'abs', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Lie on your back with the knees bent over the hips. Curl the pelvis up and roll the lower back off the floor, then lower slowly without swinging the legs.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('02fc9248-36a5-4bd6-b5ae-d1b439d27fca', 'cable-woodchop', 'Cable woodchop', 'abs', array['glutes']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Stand side-on to a cable with both hands on the handle. Rotate through the trunk and pull the handle diagonally across the body, then return slowly. Do both sides.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('bcc31c55-868b-4122-a79f-09446d5e3771', 'suitcase-carry', 'Suitcase carry', 'abs', array['back']::text[], 'dumbbell', 'compound', 'distance', 'total', 'Hold one heavy dumbbell at one side, stand tall without leaning and walk with short steps. Switch hands and walk back. Log the distance covered.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('62facd36-2cc8-48b0-b7d9-73842d81ebd0', 'neck-flexion', 'Neck flexion', 'back', array[]::text[], 'other', 'isolation', 'weight_reps', 'total', 'Lie on your back with the head off the end of a bench and a light plate on the forehead, held with the hands. Slowly bring the chin to the chest, then lower. Go light, never jerk, and get advice if your neck has a problem.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('248a3d03-bebf-45d7-83fe-70dbf9f1a302', 'neck-extension', 'Neck extension', 'back', array[]::text[], 'other', 'isolation', 'weight_reps', 'total', 'Lie face down with the head off the end of a bench and a light plate behind the head, or use a neck harness. Slowly lift the head back, then lower. Go light and never force the movement.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('50a9ff8b-a96f-448a-8075-2a0ee1744728', 'dumbbell-pullover', 'Dumbbell pullover', 'back', array['chest', 'triceps']::text[], 'dumbbell', 'isolation', 'weight_reps', 'total', 'Lie across or along a bench holding one dumbbell over the chest with both hands. Keeping a slight, fixed bend in the elbows, lower it back behind the head to a comfortable stretch, then pull it back over the chest. Log the weight of the dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('c2d5b540-92d7-4fd3-a910-aa861ddaf70b', 'seated-machine-triceps-dip', 'Seated machine triceps dip', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Sit upright with the handles at your sides and the elbows close in. Press both handles down until the arms are straight, then let them rise slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('20c4a135-0225-4df2-9372-14e959010714', 'dumbbell-shrug', 'Dumbbell shrug', 'back', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Stand tall with a dumbbell in each hand at your sides. Lift the shoulders straight up towards the ears without rolling them, pause, then lower. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d48c9a8a-894a-42d6-9858-f1fde9ab6731', 'standing-cable-shoulder-press', 'Standing cable shoulder press', 'shoulders', array['triceps']::text[], 'cable', 'compound', 'weight_reps', 'per_hand', 'Stand in a split stance between two low cables with a handle in each hand at shoulder height. Press both handles overhead together without leaning back or using the legs, then lower. Log the weight of one stack.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1d43ed4f-4cc9-4fe0-a07b-30e8354a23ff', 'behind-the-neck-lat-pulldown', 'Behind-the-neck lat pulldown', 'back', array['biceps']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Sit at the pulldown with a wide overhand grip. Pull the bar down behind the head only as far as your shoulders move comfortably, keeping the head still, then return. Stop if the shoulders or neck complain.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e1e8dc46-244d-4752-9c86-ad8931b1abda', 'weighted-push-up', 'Weighted push-up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'weighted_bodyweight', 'total', 'Wear a weighted vest or have a plate placed on the upper back. With the hands about shoulder width and the body straight, lower the chest to the floor, then push up. Log only the added weight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('2b9e2c1c-096c-415c-b70a-ae6e05fb6b9a', 'weighted-standing-single-leg-calf-raise', 'Weighted standing single-leg calf raise', 'calves', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'total', 'Stand on one foot on a step holding a dumbbell, with a hand on a support for balance. With the knee nearly straight, lower the heel to a stretch, then rise as high as you can. Log the weight held and the reps for each leg.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5793d535-040c-417b-be42-3e3ea9cf27d5', 'smith-machine-shoulder-press', 'Smith machine shoulder press', 'shoulders', array['triceps']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Sit on an upright bench under the Smith bar with the bar in front of your face. Press it overhead along the fixed path, then lower to about chin height.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('303b749e-1416-42b4-8146-10a2f5db7be3', 'standing-dumbbell-shoulder-press', 'Standing dumbbell shoulder press', 'shoulders', array['triceps']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Stand tall with the dumbbells at shoulder height. Press both overhead together without bending the knees or leaning back, then lower. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('632440f2-d668-42d8-9c4f-d6eea5fe73fe', 'single-arm-dumbbell-shoulder-press', 'Single-arm dumbbell shoulder press', 'shoulders', array['triceps', 'abs']::text[], 'dumbbell', 'compound', 'weight_reps', 'total', 'Stand tall with one dumbbell at shoulder height. Press it overhead without leaning to the side or using the legs, then lower. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('3bf87b92-eddd-470a-a38c-bf62856e5fca', 'cable-rear-delt-fly', 'Cable rear delt fly', 'shoulders', array['back']::text[], 'cable', 'isolation', 'weight_reps', 'per_hand', 'Set two cables at shoulder height and take the opposite handle in each hand so the cables cross. With soft, fixed elbows, sweep both arms out and back, then return slowly. Do not row. Log the weight of one stack.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e991a055-a4ae-43b4-902c-69fa192d5b29', 'assisted-dip', 'Assisted dip', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'compound', 'assisted_bodyweight', 'total', 'Kneel or stand on the assistance pad and hold the parallel handles. Keep the torso upright and the elbows tucked, lower until the upper arms are about level, then press up. Log the assistance weight; less assistance means more work.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d3556be1-d792-44c3-ad56-8292c5b88bd1', 'dumbbell-triceps-kickback', 'Dumbbell triceps kickback', 'triceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Lean forward with one hand on a bench and the working upper arm against your side. Straighten the elbow until the arm is in line with the body, then bend it back without swinging. One arm at a time and log each side, or both arms together.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('2d5d1e90-22ff-4465-bebc-fa709942a7a9', 'cable-triceps-kickback', 'Cable triceps kickback', 'triceps', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Hold a single handle from a low cable and lean forward with the upper arm fixed at your side. Straighten the elbow until the arm is in line with the body, then return slowly. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('dcc0a4c4-7f11-4df2-8e50-9e87212e4f19', 'smith-machine-shrug', 'Smith machine shrug', 'back', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Stand with the Smith bar in front of the thighs and the arms long. Lift the shoulders straight up towards the ears without rolling them, pause, then lower.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('cb627a73-5459-455f-9614-a14755eeff18', 'incline-dumbbell-fly', 'Incline dumbbell fly', 'chest', array['shoulders']::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Lie on a bench set to about 20 to 30 degrees with the dumbbells over the chest. With soft, fixed elbows, open the arms out to a stretch, then bring them back together. Do not press. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('c0579b38-afb8-4779-a26b-977f9970bb1e', 'decline-push-up', 'Decline push-up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Put the feet on a bench or box about 30 to 45 cm high and the hands on the floor at shoulder width. Keep the body straight, lower the chest to the floor, then push up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d0c04a5b-db05-4da0-9699-a0b491e9d7fe', 'incline-push-up', 'Incline push-up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Put the hands on a bench or stable edge at shoulder width with the feet on the floor. Keep the body straight, lower the chest to the edge, then push away.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('82ae0cd4-1f88-49dc-94d1-5ad5c164e715', 'diamond-push-up', 'Diamond push-up', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Put the hands close together under the chest, thumbs and fingers forming a diamond. Keep the elbows close and the body straight, lower the chest to the hands, then push up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('da422ccf-5d08-46c0-8230-977a49a7d33c', 'reverse-grip-lat-pulldown', 'Reverse-grip lat pulldown', 'back', array['biceps']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Hold the bar with the palms facing you at shoulder width. Pull it down in front to the upper chest with little lean or swing, then let it rise to straight arms.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1dfc8994-7038-4338-8c9d-d861dddab3db', 'weighted-chin-up', 'Weighted chin-up', 'back', array['biceps']::text[], 'bodyweight', 'compound', 'weighted_bodyweight', 'total', 'Add weight with a belt or vest and hang with the palms facing you at shoulder width. Pull the chin over the bar, then lower to a full hang. Log only the added weight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('66b02a2f-fcef-4cbd-b3d8-289ee1d843fb', 'smith-machine-calf-raise', 'Smith machine calf raise', 'calves', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Stand under the Smith bar with the balls of both feet on a raised plate or step. With the knees nearly straight, lower the heels to a stretch, then rise as high as you can.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d9b6f9ef-1854-43c4-88b5-c433054c9fc8', 'standing-dumbbell-calf-raise', 'Standing dumbbell calf raise', 'calves', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Stand on a step with a dumbbell in each hand. With the knees nearly straight, lower the heels to a stretch, then rise as high as you can. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ec43d80f-ee27-45ec-afc2-d9c505c2d3da', 'barbell-wrist-curl', 'Barbell wrist curl', 'biceps', array[]::text[], 'barbell', 'isolation', 'weight_reps', 'total', 'Sit with the forearms on the thighs or a bench, palms up and wrists past the edge, holding a barbell. Curl the wrists up as far as they go, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('23652775-107a-49a6-92db-f88d594cb3b4', 'cable-wrist-curl', 'Cable wrist curl', 'biceps', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Kneel or sit facing a low cable with a straight bar, forearms supported and palms up. Curl the wrists up as far as they go, then lower slowly. With a single handle, do one hand at a time and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d24982bb-0677-4b4e-b13b-b52fd96103e8', 'dumbbell-preacher-curl', 'Dumbbell preacher curl', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Rest the back of the upper arm on the preacher pad with the palm up. Curl the dumbbell up without lifting the elbow, then lower to a nearly straight arm. One arm at a time and log each side, or both arms together.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1545fbaa-ce0f-4856-b295-df0fcd1f6b61', 'concentration-curl', 'Concentration curl', 'biceps', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'total', 'Sit with the working elbow braced against the inside of the thigh. Curl the dumbbell up to the shoulder without moving the body, then lower to a straight arm. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d1c6ade1-36d1-48fe-9ecd-19d30de6ebf1', 'reverse-barbell-wrist-curl', 'Reverse barbell wrist curl', 'biceps', array[]::text[], 'barbell', 'isolation', 'weight_reps', 'total', 'Sit with the forearms on the thighs or a bench, palms down and wrists past the edge, holding a barbell. Lift the backs of the hands up as far as they go without lifting the elbows, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('029f1cb9-5c67-44a8-a716-125e190dcb6a', 'reverse-cable-wrist-curl', 'Reverse cable wrist curl', 'biceps', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Kneel or sit facing a low cable with a straight bar, forearms supported and palms down. Lift the backs of the hands up as far as they go, then lower slowly. With a single handle, do one hand at a time and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('3d399d35-643b-4fea-a4a1-2c3195198f01', 'wrist-roller', 'Wrist roller', 'biceps', array[]::text[], 'other', 'isolation', 'weight_reps', 'total', 'Hold the roller in front with both hands, the weight hanging on its cord. Roll the weight all the way up by turning the wrists, then lower it under control. One rep is up and down. Log the hanging weight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ca04d696-e0eb-4c0c-b762-240dc93da78b', 'plate-pinch-hold', 'Plate pinch hold', 'biceps', array[]::text[], 'other', 'isolation', 'duration', 'total', 'Pinch smooth weight plates together between the thumb and fingers of one hand, arm hanging at your side. Hold for time, then switch hands. Log each hand as its own set.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('894a956a-ad26-4f2e-81bf-75ba55f8bb31', 'single-arm-cable-shoulder-press', 'Single-arm cable shoulder press', 'shoulders', array['triceps', 'abs']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Stand in a split stance with a single handle from a low cable at shoulder height. Press it overhead without twisting the trunk, then lower. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1f54f488-9319-4ae7-b538-ff8ec5f66378', 'cable-front-raise', 'Cable front raise', 'shoulders', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Face away from a low cable holding the handle at your side. Raise the straight arm in front to shoulder height, then lower slowly. One arm at a time and log each side, or both hands on a bar.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('29c9c73c-5ec0-4cd2-9620-27cc25861324', 'incline-dumbbell-shrug', 'Incline dumbbell shrug', 'back', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Lie chest down on a bench set to 30 to 45 degrees with the dumbbells hanging. Keeping the arms straight, lift the shoulders up towards the ears and slightly back, then lower. Do not row. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('2412f5b4-9970-40bc-bc88-5027e96cc7eb', 'behind-the-back-barbell-shrug', 'Behind-the-back barbell shrug', 'back', array[]::text[], 'barbell', 'isolation', 'weight_reps', 'total', 'Hold a barbell behind the thighs with straight arms. Lift the shoulders straight up towards the ears, pause, then lower.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('da6fbad2-c441-4459-bb20-086d39cd1707', 'single-arm-straight-arm-pulldown', 'Single-arm straight-arm pulldown', 'back', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Face a high cable holding a single handle with a soft, fixed elbow. Pull the hand down in an arc to the hip without bending the elbow, then return slowly. Do one arm, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('95204235-1054-4b57-9ca4-77eee94b5b9b', 'seated-single-leg-calf-raise', 'Seated single-leg calf raise', 'calves', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Sit with one forefoot on the step and the knee bent to about 90 degrees under the pad, or with a dumbbell on the thigh. Lower the heel to a stretch, then rise as high as you can. Do one leg, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1b4ea2f7-8dae-495c-ab77-d8853dbfebb0', 'weighted-tibialis-raise', 'Weighted tibialis raise', 'calves', array[]::text[], 'other', 'isolation', 'weight_reps', 'total', 'Sit or stand with the heels supported and both feet under a tibialis machine pad or tib bar. Pull the toes and fronts of the feet up as high as you can, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('0c11318b-c4e7-4255-b907-59cbe9c873c3', 'neck-lateral-flexion', 'Neck lateral flexion', 'back', array[]::text[], 'other', 'isolation', 'weight_reps', 'total', 'Lie on your side with the head off the end of a bench, or use a harness or your hand for resistance. Slowly bend the ear towards the shoulder and back, without turning the head. Go light, do one side, then the other, and log each side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
on conflict (id) do update set
  key = excluded.key,
  name = excluded.name,
  primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles,
  equipment = excluded.equipment,
  category = excluded.category,
  tracking_type = excluded.tracking_type,
  load_mode = excluded.load_mode,
  instructions = excluded.instructions,
  updated_at = excluded.updated_at;
